#pragma once
#include <Arduino.h>
#include "config.hpp"

// Event types generated by the HW-040 rotary wheel
enum WheelEventType {
    WHEEL_EVENT_NONE = 0,
    WHEEL_EVENT_ROT_CW,       // Rotated clockwise (navigate down / next)
    WHEEL_EVENT_ROT_CCW,      // Rotated counter-clockwise (navigate up / prev)
    WHEEL_EVENT_CLICK,        // Push button pressed and released (<600ms)
    WHEEL_EVENT_LONG_PRESS    // Push button held for >= 600ms
};

// Global task handle for the wheel scanning task
extern TaskHandle_t wheelTaskHandle;

// Initialize HW-040 GPIO pins and FreeRTOS event queue
bool initWheel();

// Poll for an available wheel event (non-blocking by default)
bool getWheelEvent(WheelEventType& outEvent, TickType_t waitTicks = 0);

// FreeRTOS background task scanning wheel state with debouncing
void wheelTask(void *pvParameters);

